// Podpowiedzi (od kierunku myślenia do pierwszego kroku – bez wyniku) i typowe pułapki do zadań z arkuszy CKE.
// Pokazywane tylko w zakładce „Zadania” (ckeTasksOfTopic) – w trybie arkusza zadania są jak na maturze, bez pomocy.
// Klucz: id zadania (`cke-<rok>-maj[-r]-<numer>`). Pułapka – tylko przy zadaniach zamkniętych (karta po błędnej odpowiedzi).

export type CkeHelp = { hints: string[]; trap?: string };

const h = (hints: string[], trap?: string): CkeHelp => (trap ? { hints, trap } : { hints });

